import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';

const order = ['validate.js', 'store_sql.js', 'store_d1.js', 'api.js', 'index.js'];
let out = '// Generated by `node bundle.js`, paste this whole file into the Cloudflare dashboard editor.\n';
for (const file of order) {
  const code = readFileSync(new URL(`./src/${file}`, import.meta.url), 'utf8')
    .replace(/\r\n/g, '\n')
    .replace(/^import .*;\n/gm, '')
    .replace(/^export (?!default)/gm, '');
  out += `\n${code}`;
}
mkdirSync(new URL('./dist/', import.meta.url), { recursive: true });
writeFileSync(new URL('./dist/worker.js', import.meta.url), out);
console.log(`dist/worker.js, ${out.length} bytes`);
